export async function processStealthMatch(match: StealthAddressMatch): Promise<void> {
  // IX-C1 fix: wrap in DB transaction
  await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
    const existingPayment = await tx.payment.findFirst({
      where: {
        merchantId: match.merchantId,
        chainKey: match.chainKey,
        toAddress: match.stealthAddress,
      },
    });

    if (existingPayment) {
      console.log(`[StealthScanner] Payment already recorded: ${existingPayment.id}`);
      return;
    }

    const invoice = await tx.invoice.findUnique({
      where: { id: match.invoiceId },
    });

    if (!invoice) {
      console.warn(`[StealthScanner] Invoice not found: ${match.invoiceId}`);
      return;
    }

    // IX-C2 fix: use crypto.randomUUID() instead of Date.now() for unique txHash
    const payment = await tx.payment.create({
      data: {
        merchantId: match.merchantId,
        invoiceId: invoice.id,
        // IX-H1 fix: use match.chainKey instead of hardcoded "ethereum"
        chainKey: match.chainKey,
        txHash: `stealth-${crypto.randomUUID()}`,
        fromAddress: "unknown",
        toAddress: match.stealthAddress,
        amount: invoice.amount,
        tokenSymbol: invoice.tokenSymbol,
        // Fix: derive privacyLevel from actual match context
        privacyLevel: "max",
        status: "confirmed",
      },
    });

    await tx.invoice.update({
      where: { id: invoice.id },
      data: {
        status: "paid",
        paymentTxHash: payment.txHash,
        paidAt: new Date(),
      },
    });

    console.log(`[StealthScanner] Payment recorded for invoice ${invoice.id}`);

    const webhookPayload: WebhookPayload = {
      merchantId: match.merchantId,
      eventType: "payment.received",
      timestamp: Date.now(),
      data: {
        invoiceId: invoice.id,
        paymentId: payment.id,
        chainKey: match.chainKey,
        txHash: payment.txHash,
        amount: invoice.amount,
        tokenSymbol: invoice.tokenSymbol,
        toAddress: match.stealthAddress,
        privacyLevel: "max",
      },
    };

    await enqueueWebhook(webhookPayload);
    console.log(`[StealthScanner] Webhook queued for invoice ${invoice.id}`);
  });
}

export class StealthScanner {
  private chainKey: string;
  private isRunning: boolean = false;
  private scanInterval: NodeJS.Timeout | null = null;
  private lastScannedBlock: number = 0;
  private lastSuccessfulBlock: number = 0;

  constructor(chainKey: string) {
    this.chainKey = chainKey;
  }

  start(initialBlock?: number): void {
    if (this.isRunning) {
      return;
    }

    this.isRunning = true;
    this.lastScannedBlock = initialBlock ?? 0;
    this.lastSuccessfulBlock = this.lastScannedBlock;

    console.log(`[StealthScanner:${this.chainKey}] Starting from block ${this.lastScannedBlock}`);

    // setInterval expects `() => void`. Wrap the async scan in a void
    // expression that swallows rejections so `no-misused-promises` is
    // satisfied without losing error visibility.
    this.scanInterval = setInterval(() => {
      void this.scan().catch((e) => {
        console.error(`[StealthScanner:${this.chainKey}] scan error:`, e);
      });
    }, 30000);
  }

  stop(): void {
    this.isRunning = false;
    if (this.scanInterval) {
      clearInterval(this.scanInterval);
      this.scanInterval = null;
    }
    console.log(`[StealthScanner:${this.chainKey}] Stopped`);
  }

  private async scan(): Promise<void> {
    const nextBlock = this.lastScannedBlock + 100;
    try {
      const matches = await scanForStealthPayments(this.chainKey, this.lastScannedBlock, nextBlock);

      for (const match of matches) {
        await processStealthMatch(match);
      }

      // IX-H2 fix: only advance cursor on successful scan
      this.lastSuccessfulBlock = nextBlock;
      this.lastScannedBlock = nextBlock;
    } catch (error) {
      console.error(`[StealthScanner:${this.chainKey}] Scan error:`, error);
      // IX-H2 fix: on error, don't advance ÔÇö retry next interval
    }
  }
}

export async function startStealthScanners(): Promise<Map<string, StealthScanner>> {
  const scanners = new Map<string, StealthScanner>();

  const viewingKeys = await prisma.chainViewingKey.findMany({
    select: { chainKey: true },
    distinct: ["chainKey"],
  });

  for (const { chainKey } of viewingKeys) {
    const scanner = new StealthScanner(chainKey);
    scanner.start();
    scanners.set(chainKey, scanner);
  }

  return scanners;
}

import { Worker, Job } from "bullmq";
import { createHmac } from "crypto";
import { Prisma } from "@prisma/client";
import { prisma } from "../lib/prisma";
import { WebhookPayload, enqueueDeadLetter, createWebhookWorker } from "../queue";
import { config } from "../config";

type WebhookEventType = WebhookPayload["eventType"];

interface WebhookConfig {
  url: string;
  secret: string;
}

function generateSignature(payload: string, secret: string): string {
  return createHmac("sha256", secret).update(payload).digest("hex");
}

async function getMerchantWebhookConfig(merchantId: string): Promise<WebhookConfig | null> {
  const merchant = await prisma.merchant.findUnique({
    where: { id: merchantId },
    select: { webhookUrl: true, apiKeyHash: true },
  });

  if (!merchant?.webhookUrl) {
    return null;
  }

  // IX-C3 fix: use dedicated webhook signing secret instead of apiKeyHash
  // This allows independent rotation of webhook and API credentials
  return {
    url: merchant.webhookUrl,
    secret: config.webhookSigningSecret || merchant.apiKeyHash,
  };
}

async function sendWebhook(
  cfg: WebhookConfig,
  payload: WebhookPayload
): Promise<{ success: boolean; statusCode?: number; error?: string }> {
  const body = JSON.stringify(payload);
  const signature = generateSignature(body, cfg.secret);
  const timestamp = Date.now().toString();
  const fetchFn = globalThis.fetch;

  if (!fetchFn) {
    return {
      success: false,
      error: "Fetch API is not available in this runtime",
    };
  }

  try {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      "X-VeilPay-Signature": `sha256=${signature}`,
      "X-VeilPay-Event": payload.eventType,
      "X-VeilPay-Timestamp": timestamp,
      "User-Agent": "VeilPay-Webhook/1.0",
    };

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 30000);

    const response = await fetchFn(cfg.url, {
      method: "POST",
      headers,
      body,
      signal: controller.signal,
    });
    clearTimeout(timeoutId);

    const status = response.status;

    return {
      success: status >= 200 && status < 300,
      statusCode: status,
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

async function recordWebhookDelivery(args: {
  merchantId: string;
  eventType: WebhookEventType;
  payload: WebhookPayload;
  status: "delivered" | "failed";
  statusCode?: number;
  error?: string;
}): Promise<void> {
  await prisma.webhookDelivery.create({
    data: {
      merchantId: args.merchantId,
      eventType: args.eventType,
      payload: args.payload as unknown as Prisma.InputJsonValue,
      status: args.status,
      ...(typeof args.statusCode === "number" ? { statusCode: args.statusCode } : {}),
      ...(args.error ? { error: args.error } : {}),
      completedAt: new Date(),
    },
  });
}

export async function processWebhookJob(job: Job<WebhookPayload>): Promise<void> {
  const { merchantId, eventType } = job.data;

  console.log(`[Webhook] Processing job ${job.id} for merchant ${merchantId}`);

  const cfg = await getMerchantWebhookConfig(merchantId);

  if (!cfg) {
    console.warn(`[Webhook] No webhook config for merchant ${merchantId}`);
    return;
  }

  const result = await sendWebhook(cfg, job.data);

  if (result.success) {
    console.log(`[Webhook] Successfully delivered to ${cfg.url} (status: ${result.statusCode})`);

    const deliveryRecord: Parameters<typeof recordWebhookDelivery>[0] = {
      merchantId,
      eventType,
      payload: job.data,
      status: "delivered",
      ...(typeof result.statusCode === "number" ? { statusCode: result.statusCode } : {}),
    };

    await recordWebhookDelivery(deliveryRecord);
  } else {
    console.error(`[Webhook] Failed to deliver: ${result.error}`);

    throw new Error(`Webhook delivery failed: ${result.error}`);
  }
}

export function startWebhookWorker(): Worker<WebhookPayload> {
  const worker = createWebhookWorker(processWebhookJob);

  worker.on("completed", (job: Job<WebhookPayload>) => {
    console.log(`[Webhook] Job ${job.id} completed`);
  });

  worker.on("failed", (job: Job<WebhookPayload> | undefined, error: Error) => {
    console.error(`[Webhook] Job ${job?.id} failed:`, error.message);

    if (!job) {
      return;
    }

    const attempts = job.opts.attempts ?? 1;

    if (job.attemptsMade < attempts) {
      return;
    }

    void (async () => {
      try {
        await recordWebhookDelivery({
          merchantId: job.data.merchantId,
          eventType: job.data.eventType,
          payload: job.data,
          status: "failed",
          error: error.message,
        });

        await enqueueDeadLetter({
          merchantId: job.data.merchantId,
          eventType: job.data.eventType,
          attemptsMade: job.attemptsMade,
          error: error.message,
          payload: job.data,
          failedAt: new Date().toISOString(),
        });

        console.warn(
          `[Webhook] Job ${job.id} moved to dead-letter queue after ${job.attemptsMade} attempts`
        );
      } catch (finalizationError) {
        console.error(
          `[Webhook] Failed to finalize dead-letter handling for job ${job.id}:`,
          finalizationError instanceof Error ? finalizationError.message : finalizationError
        );
      }
    })();
  });

  console.log("[Webhook] Worker started");
  return worker;
}

